+static bool
+profile_name_is_valid(const char* name)
+{
+    bool valid = true;
+
+#ifdef _WIN32
+    char* invalid_dir_char = "\\/:*?\"<>|";
+    int i;
+
+    for (i = 0; i < 9; i++) {
+        if (strchr(name, invalid_dir_char[i])) {
+            /* Invalid character in directory */
+            valid = false;
+        }
+    }
+    if (name[0] == '.' || name[strlen(name) - 1] == '.') {
+        /* Profile name cannot start or end with period */
+        valid = false;
+    }
+#else
+    if (strchr(name, '/')) {
+        /* Invalid character in directory */
+        valid = false;
+    }
+#endif
+
+    return valid;
+}
