+bool ProfileItem::profileSavePreferences(const QString& profileSettingsPath, QString appName, std::function<void(const QString& error)> errorHandler)
+{
+    QFile file(profileSettingsPath);
+    if (!file.open(QIODevice::WriteOnly | QIODevice::Text))
+    {
+        QString err = QObject::tr("Can't open profile settings file\n\"%1\": %2.").arg(profileSettingsPath, file.errorString());
+        errorHandler(err);
+        return false;
+    }
+
+    QString formattedString = QObject::tr("# \"%1\" profile settings file for %2 " VERSION ". Edit with care.\n").arg(getName(), appName);
+    file.write(formattedString.toUtf8());
+
+    formattedString = QObject::tr("\n# Automatically switch to this profile if this display filter matches.\n");
+    file.write(formattedString.toUtf8());
+
+    formattedString = QString("%1: %2\n").arg(AUTO_SWITCH_FILTER_KEY).arg(autoSwitchFilter_);
+    file.write(formattedString.toUtf8());
+
+    file.close();
+
+    return true;
+}
